-- ============================================================
-- HEALTHCARE_DB  —  Enhanced Schema v2
-- Added: doctors table, DoctorID in patients, realistic lab
--        time-series (3-5 rows/patient), correct normal ranges
-- ============================================================

CREATE DATABASE HEALTHCARE_DB_V2;
USE HEALTHCARE_DB_V2;

-- ── Lookup tables ──────────────────────────────────────────
CREATE TABLE diagnoses (
    DiagnosisID   INT PRIMARY KEY,
    DiagnosisName VARCHAR(100)
);

CREATE TABLE outcomes (
    OutcomeID   INT PRIMARY KEY,
    OutcomeName VARCHAR(50)
);

CREATE TABLE departments (
    DepartmentID   INT PRIMARY KEY,
    DepartmentName VARCHAR(100)
);

CREATE TABLE doctors (
    DoctorID     INT PRIMARY KEY,
    DoctorName   VARCHAR(100),
    Gender       CHAR(1),
    DepartmentID INT,
    Specialty    VARCHAR(100),
    ExperienceYears INT,
    FOREIGN KEY (DepartmentID) REFERENCES departments(DepartmentID)
);

CREATE TABLE patients (
    PatientID     INT PRIMARY KEY,
    Name          VARCHAR(100),
    Age           INT,
    Gender        CHAR(1),
    DiagnosisID   INT,
    DoctorID      INT,
    AdmissionDate DATE,
    DischargeDate DATE,
    OutcomeID     INT,
    TreatmentCost INT,
    FOREIGN KEY (DiagnosisID) REFERENCES diagnoses(DiagnosisID),
    FOREIGN KEY (DoctorID)    REFERENCES doctors(DoctorID),
    FOREIGN KEY (OutcomeID)   REFERENCES outcomes(OutcomeID)
);

CREATE TABLE labs (
    LabID         INT PRIMARY KEY,
    PatientID     INT,
    TestName      VARCHAR(100),
    Result        DECIMAL(10,2),
    NormalRange   VARCHAR(50),
    TestDate      DATE,
    FOREIGN KEY (PatientID) REFERENCES patients(PatientID)
);

